<!doctype html>
<html lang="ru">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>PAPACHEAT — игровой софт</title>
    <style>
        :root{font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#f4f7f3;background:#090b0d}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(circle at 80% -10%,#263c20 0,transparent 35%),linear-gradient(145deg,#090b0d,#111711 55%,#090b0d)}a{color:inherit;text-decoration:none}.wrap{max-width:1160px;margin:auto;padding:24px}.nav{display:flex;align-items:center;justify-content:space-between;padding:12px 0 34px}.brand{display:flex;align-items:center;gap:12px;font-weight:900;letter-spacing:.12em}.mark{width:42px;height:42px;display:grid;place-items:center;border:1px solid #b7ff3c;border-radius:12px;color:#b7ff3c;font-size:22px;box-shadow:0 0 30px #9dff352b}.navlinks{display:flex;gap:20px;color:#a8b1aa;font-size:14px}.pill{border:1px solid #31432d;border-radius:999px;padding:9px 14px;color:#d5e2d1}.hero{display:grid;grid-template-columns:1.2fr .8fr;gap:24px;align-items:end;padding:44px 0 56px}.eyebrow{color:#b7ff3c;text-transform:uppercase;letter-spacing:.18em;font-size:12px;font-weight:800}.hero h1{font-size:clamp(42px,7vw,82px);line-height:.95;margin:15px 0 22px;max-width:760px}.hero p{color:#a8b1aa;max-width:620px;font-size:18px;line-height:1.6}.hero-card{min-height:230px;border:1px solid #32452d;border-radius:24px;padding:24px;background:linear-gradient(150deg,#182317,#101511);position:relative;overflow:hidden}.hero-card:after{content:"";position:absolute;width:180px;height:180px;border-radius:50%;right:-40px;bottom:-60px;background:#b7ff3c22;filter:blur(5px)}.hero-stat{font-size:54px;font-weight:900;color:#b7ff3c}.section-head{display:flex;justify-content:space-between;align-items:end;margin-bottom:18px}.section-head h2{font-size:28px;margin:0}.muted{color:#8d998f}.games{display:flex;gap:10px;margin-bottom:22px}.game{cursor:pointer;background:#111812;border:1px solid #2c3b2b;color:#aab7a6;border-radius:12px;padding:11px 17px}.game.active{background:#b7ff3c;color:#10150e;border-color:#b7ff3c;font-weight:800}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card{background:#111512;border:1px solid #29362a;border-radius:18px;padding:20px;transition:.2s}.card:hover{transform:translateY(-4px);border-color:#b7ff3c88;box-shadow:0 16px 40px #0008}.card-top{display:flex;justify-content:space-between;gap:10px}.tag{font-size:11px;color:#b7ff3c;border:1px solid #466238;border-radius:999px;padding:5px 9px}.card h3{font-size:22px;margin:22px 0 8px}.card p{min-height:68px;color:#9da89f;line-height:1.5;font-size:14px}.price{font-size:25px;font-weight:900}.buy{display:block;text-align:center;background:#b7ff3c;color:#11170d;border-radius:10px;padding:12px;margin-top:16px;font-weight:900}.status{display:flex;align-items:center;gap:7px;font-size:12px;color:#b8d6a9}.dot{width:7px;height:7px;border-radius:50%;background:#8dff59;box-shadow:0 0 12px #8dff59}.footer{padding:60px 0 22px;color:#6f7c70;font-size:13px}@media(max-width:800px){.hero{grid-template-columns:1fr;padding-top:22px}.grid{grid-template-columns:1fr}.navlinks{display:none}}
    </style>
</head>
<body>
<div class="wrap">
    <nav class="nav"><a class="brand" href="/"><span class="mark">P</span><span>PAPACHEAT<br><small style="color:#b7ff3c;font-size:9px;letter-spacing:.2em">NEXT LEVEL PLAY GG!</small></span></a><div class="navlinks"><a href="#catalog">Каталог</a><a href="#about">О магазине</a><a class="pill" href="#account">Личный кабинет</a></div></nav>
    <section class="hero"><div><div class="eyebrow">Игровое ПО нового уровня</div><h1>Твой рейд.<br><span style="color:#b7ff3c">Твои правила.</span></h1><p>Проверенные программы для Arena Breakout: Infinite и DayZ. Выбирай игру, открывай каталог и получай поддержку после покупки.</p></div><div class="hero-card"><div class="muted">Сейчас в каталоге</div><div class="hero-stat">2 игры</div><div class="status"><span class="dot"></span> Все продукты имеют статус Undetected</div></div></section>
    <section id="catalog"><div class="section-head"><div><div class="eyebrow">Каталог</div><h2>Выбери игру</h2></div><span class="muted">Обновлено сегодня</span></div><div class="games"><button class="game active" data-game="arena">Arena Breakout: Infinite</button><button class="game" data-game="dayz">DayZ</button></div><div class="grid" id="products"></div></section>
    <section id="about" class="footer">PAPACHEAT · NEXT LEVEL PLAY GG!<br>Поддержка и обработка заказов доступны в личном кабинете.</section>
</div>
<script>
const products={arena:[['Tundra WEB Radar','500 ₽','Браузерный радар с картой рейда, игроками, ИИ, лутом и выходами.','1 день'],['SPOOFER','5 000 ₽','HWID Spoofer для Arena Breakout: Infinite. Windows 10/11 x64.','На один раз'],['SPOOFER — навсегда','12 000 ₽','HWID Spoofer с ключом навсегда для Arena Breakout: Infinite.','Навсегда'],['Lag Switch','1 000 ₽','Программа имитирует высокую задержку или кратковременную потерю пакетов.','Навсегда']],dayz:[['Lag Switch','1 000 ₽','Программа имитирует высокую задержку или кратковременную потерю пакетов.','Навсегда']]};
const root=document.querySelector('#products');function render(game){root.innerHTML=products[game].map(p=>`<article class="card"><div class="card-top"><span class="tag">UNDETECTED</span><span class="muted">${p[3]}</span></div><h3>${p[0]}</h3><p>${p[2]}</p><div class="price">${p[1]}</div><a class="buy" href="#account">Подробнее и купить</a></article>`).join('')};render('arena');document.querySelectorAll('.game').forEach(b=>b.onclick=()=>{document.querySelectorAll('.game').forEach(x=>x.classList.remove('active'));b.classList.add('active');render(b.dataset.game)});
</script>
</body>
</html>
